    def flush():
        sys.stdout.flush()

    def query(i, j):
        print(f"? {i} {j}")
        flush()
        return input().strip()

    def solve(n):
        players = list(range(1, 2 * n + 1))
        stack = []
        while len(players) > 1:
            if len(players) % 2 == 1:
                stack.append(players.pop())
            p1, p2 = players.pop(), players.pop()
            winner = query(p1, p2)
            if winner == '>':
                players.append(p1)
            else:
                players.append(p2)
        strongest = players[0]
        while stack:
            p = stack.pop()
            winner = query(strongest, p)
            if winner == '<':
                strongest = p

        selected = [strongest]
        remaining = set(range(1, 2 * n + 1)) - {strongest}
        for _ in range(n - 1):
            p = remaining.pop()
            while remaining:
                q = remaining.pop()
                winner = query(p, q)
                if winner == '>':
                    remaining.add(q)
                else:
                    remaining.add(p)
                    p = q
            selected.append(p)

        # Ensure there are at least two possible orderings among the selected players
        query(selected[0], selected[1])

        print('!')
        flush()

    t = int(input().strip())
    for _ in range(t):
        n = int(input().strip())
        solve(n)

